- Και δεν έχετε εκτός από τον Αλλάχ ούτε προστάτη ούτε βοηθό. (وَمَا لَكُم مِّن دُونِ اللَّهِ مِن وَلِيٍّ وَلَا نَصِيرٍ) 2:107; 9:116; 29:22; 42:31
- Θα τους συγχωρήσω τις αμαρτίες τους και θα τους εισάγω σε κήπους κάτω από τους οποίους ρέουν ποταμοί. (لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ) 3:195; 5:12; 64:9; 66:8
- Θα τους εισάγουμε σε κήπους κάτω από τους οποίους ρέουν ποταμοί, όπου θα μείνουν αιώνια. (سَنُدْخِلُهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا) 4:57; 4:122; 64:9; 65:11
- Ο Κύριός σου γνωρίζει καλύτερα ποιος ξεστράτισε από το δρόμο Του, και Αυτός γνωρίζει καλύτερα. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 16:125; 53:30; 68:7
- Θα επιστραφείτε στον Γνώστη του αόρατου και του φανερού, και θα σας ενημερώσει για όσα κάνατε. (تُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:94; 9:105; 62:8
- Σκότωναν τους γιους σας και άφηναν τις γυναίκες σας ζωντανές· σε αυτό υπήρχε μεγάλη δοκιμασία από τον Κύριό σας. (أَبْنَاءَكُمْ وَيَسْتَحْيُونَ نِسَاءَكُمْ وَفِي ذَلِكُم بَلَاءٌ مِّن رَّبِّكُمْ عَظِيمٌ) 2:49; 7:141; 14:6
- Αλήθεια, ο Κύριός σου γνωρίζει καλύτερα ποιος ξεστρατίζει από το δρόμο Του, και Αυτός. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 16:125; 53:30; 68:7
- Του Αλλάχ, που ανήκει ό,τι υπάρχει στους ουρανούς και ό,τι υπάρχει στη γη. (اللَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 14:2; 34:1; 42:53
- Ανάμεσα σε έθνη που πέρασαν πριν από εσάς, από τζιν και ανθρώπους. (فِي أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ الْجِنِّ وَالْإِنسِ) 7:38; 41:25; 46:18
- Λατρεύετε τον Αλλάχ, δεν έχετε άλλο θεό εκτός από Αυτόν, δεν θα φοβηθείτε; (اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 7:65; 23:23; 23:32
- Και βάλαμε επικαλύμματα στις καρδιές τους, για να μην το καταλαβαίνουν, και στα αυτιά τους βάρος. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 6:25; 17:46; 18:57
- Θα κρίνει ανάμεσά τους την Ημέρα της Ανάστασης για όσα διαφωνούσαν. (يَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ) 2:113; 16:124; 22:69
- Είπε: "Λαέ μου! Τι γνώμη έχετε, αν εγώ έχω ξεκάθαρο σημάδι από τον Κύριό μου;" (قَالَ يَاقَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَى بَيِّنَةٍ مِّن رَّبِّي) 11:28; 11:63; 11:88
- Αυτό, για όσα έστειλαν μπροστά τα χέρια σας, και ο Αλλάχ δεν είναι άδικος στους δούλους. (ذَلِكَ بِمَا قَدَّمَتْ أَيْدِيكُمْ وَأَنَّ اللَّهَ لَيْسَ بِظَلَّامٍ لِّلْعَبِيدِ) 3:182; 8:51; 22:10
- Για αυτούς σε αυτόν τον κόσμο υπάρχει ντροπή, και για αυτούς στον άλλο κόσμο υπάρχει μεγάλη τιμωρία. (لَهُمْ فِي الدُّنْيَا خِزْيٌ وَلَهُمْ فِي الْآخِرَةِ عَذَابٌ عَظِيمٌ) 2:114; 5:41
- Ό,τι υπάρχει στους ουρανούς και ό,τι υπάρχει στη γη, και ο Αλλάχ είναι αρκετός ως Προστάτης. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَكَفَى بِاللَّهِ وَكِيلًا) 4:132; 4:171
- Εκτός από εκείνους που πίστεψαν και έκαναν καλά έργα· για αυτούς υπάρχει αδιάλειπτη ανταμοιβή. (إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ) 84:25; 95:6
- Για να μου προσθέτεις συντρόφους για τα οποία δεν έχεις γνώση· μην τους υπακούς. (لِتُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا) 29:8; 31:15
- Αλήθεια, αυτό είναι μια υπενθύμιση· όποιος θέλει, ας πάρει έναν δρόμο προς τον Κύριό του. (إِنَّ هَذِهِ تَذْكِرَةٌ فَمَن شَاءَ اتَّخَذَ إِلَى رَبِّهِ سَبِيلًا) 73:19; 76:29
- Και όποιος είναι ευγνώμων, είναι ευγνώμων για τον εαυτό του· και όποιος είναι αχάριστος. (وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ) 27:40; 31:12
- Εκείνοι που εκτελούν την προσευχή, δίνουν την ελεημοσύνη και πιστεύουν βέβαια στην άλλη ζωή. (الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُم بِالْآخِرَةِ هُمْ يُوقِنُونَ) 27:3; 31:4
- Στον Αβραάμ, στον Ισμαήλ, στον Ισαάκ, στον Ιακώβ και στις φυλές, και σε ό,τι δόθηκε στον Μωυσή και στον Ιησού. (إِبْرَاهِيمَ وَإِسْمَاعِيلَ وَإِسْحَاقَ وَيَعْقُوبَ وَالْأَسْبَاطِ وَمَا أُوتِيَ مُوسَى وَعِيسَى) 2:136; 3:84
- Κατά ομάδες, μέχρι να φτάσουν σε αυτό, και οι πύλες του θα ανοίξουν, και οι φύλακές του θα τους πουν. (زُمَرًا حَتَّى إِذَا جَاءُوهَا فُتِحَتْ أَبْوَابُهَا وَقَالَ لَهُمْ خَزَنَتُهَا) 39:71; 39:73
- Ο Αλλάχ δεν θα σας λογοδοτήσει για τις μάταιες ορκωμοσίες σας, αλλά θα σας λογοδοτήσει για ό,τι. (لَّا يُؤَاخِذُكُمُ اللَّهُ بِاللَّغْوِ فِي أَيْمَانِكُمْ وَلَكِن يُؤَاخِذُكُم بِمَا) 2:225; 5:89
- Έλεος, χαίρονται με αυτό, και αν τους χτυπήσει κακό για όσα έστειλαν μπροστά τα χέρια τους. (رَحْمَةً فَرِحُوا بِهَا وَإِن تُصِبْهُمْ سَيِّئَةٌ بِمَا قَدَّمَتْ أَيْدِيهِمْ) 30:36; 42:48
- Κήποι κάτω από τους οποίους ρέουν ποταμοί, όπου θα μείνουν αιώνια, και πόσο ωραία είναι η ανταμοιβή των εργατών! (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَنِعْمَ أَجْرُ الْعَامِلِينَ) 3:136; 29:58
- Ο Αλλάχ γνωρίζει ό,τι υπάρχει στους ουρανούς και ό,τι υπάρχει στη γη, και ο Αλλάχ. (اللَّهُ وَيَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَاللَّهُ) 3:29; 49:16
- Υπακούτε στον Αλλάχ και υπακούτε στον Απόστολο· και αν αποστραφείτε, τότε σε αυτόν βαρύνει. (أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ فَإِن تَوَلَّوْا فَإِنَّمَا عَلَيْهِ) 24:54; 64:12
- Έχουν την ανταμοιβή τους κοντά στον Κύριό τους, και δεν υπάρχει φόβος πάνω τους, και αυτοί. (فَلَهُمْ أَجْرُهُمْ عِندَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ) 2:274; 2:277
- Και είπαν: "Όταν γίνουμε κόκαλα και σκόνη, θα αναστηθούμε πράγματι ως μια νέα δημιουργία;" (وَقَالُوا أَإِذَا كُنَّا عِظَامًا وَرُفَاتًا أَإِنَّا لَمَبْعُوثُونَ خَلْقًا جَدِيدًا) 17:49; 17:98
- Και δεν βρίσκουν για τον εαυτό τους εκτός από τον Αλλάχ ούτε προστάτη ούτε βοηθό. (وَلَا يَجِدُونَ لَهُم مِّن دُونِ اللَّهِ وَلِيًّا وَلَا نَصِيرًا) 4:173; 33:17
- "Πόσο έμεινες;" Είπε: "Έμεινα μια μέρα ή μέρος μιας μέρας." Είπε. (كَمْ لَبِثْتَ قَالَ لَبِثْتُ يَوْمًا أَوْ بَعْضَ يَوْمٍ قَالَ) 2:259; 18:19
- Μέχρι την Ημέρα της Ανάστασης, ποιος θεός εκτός από τον Αλλάχ θα μπορούσε να σας φέρει; (سَرْمَدًا إِلَى يَوْمِ الْقِيَامَةِ مَنْ إِلَهٌ غَيْرُ اللَّهِ يَأْتِيكُم) 28:71; 28:72
- Όποιος κάνει καλό, άντρας ή γυναίκα, και είναι πιστός. (مَنْ عَمِلَ صَالِحًا مِّن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ) 16:97; 40:40
- Εκείνοι που αποτρέπουν από τον δρόμο του Αλλάχ και τον θέλουν στρεβλό, και εκείνοι στην άλλη ζωή. (الَّذِينَ يَصُدُّونَ عَن سَبِيلِ اللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِالْآخِرَةِ) 7:45; 11:19
- Φάτε όπου θέλετε, αλλά μην πλησιάσετε αυτό το δέντρο, για να μη γίνετε άδικοι. (حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَذِهِ الشَّجَرَةَ فَتَكُونَا مِنَ الظَّالِمِينَ) 2:35; 7:19
- Πες: "Λαέ μου! Δράστε ανάλογα με τη θέση σας, εγώ επίσης δρω, και σύντομα θα μάθετε." (قُلْ يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 39:39
- Αλήθεια, οι χαμένοι είναι εκείνοι που έχασαν τον εαυτό τους και τις οικογένειές τους την Ημέρα της Ανάστασης, αλήθεια. (إِنَّ الْخَاسِرِينَ الَّذِينَ خَسِرُوا أَنفُسَهُمْ وَأَهْلِيهِمْ يَوْمَ الْقِيَامَةِ أَلَا) 39:15; 42:45
- Όποιος οδηγείται, οδηγείται για τον εαυτό του· και όποιος ξεστρατίζει, ξεστρατίζει για τον εαυτό του· και. (يَهْتَدِي لِنَفْسِهِ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيْهَا وَمَا) 10:108; 39:41
- Και όσοι απιστούν λένε: "Γιατί δεν του κατέβηκε ένα σημάδι από τον Κύριό του;" (وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنزِلَ عَلَيْهِ آيَةٌ مِّن رَّبِّهِ) 13:7; 13:27
- Αυτός που έκανε για εσάς τη νύχτα για να ξεκουράζεστε σε αυτήν, και την ημέρα για να βλέπετε, αλήθεια. (الَّذِي جَعَلَ لَكُمُ اللَّيْلَ لِتَسْكُنُوا فِيهِ وَالنَّهَارَ مُبْصِرًا إِنَّ) 10:67; 40:61
- Πριν έρθει η Ημέρα που δεν θα υπάρχει ούτε εμπόριο ούτε φιλία. (مِّن قَبْلِ أَن يَأْتِيَ يَوْمٌ لَّا بَيْعٌ فِيهِ وَلَا) 2:254; 14:31
- Για να σκεφτούν ότι ο σύντροφός τους δεν έχει τρέλα· είναι μόνο ένας προειδοποιητής. (يَتَفَكَّرُوا مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ) 7:184; 34:46
- Θα μείνουν αιώνια σε αυτά, η τιμωρία δεν θα ελαφρυνθεί για αυτούς, και δεν θα τους δοθεί αναβολή. (خَالِدِينَ فِيهَا لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ) 2:162; 3:88
- Μην απλώνεις τα μάτια σου σε όσα δώσαμε σε μερικούς από αυτούς για απόλαυση. (لَا تَمُدَّنَّ عَيْنَيْكَ إِلَى مَا مَتَّعْنَا بِهِ أَزْوَاجًا مِّنْهُمْ) 15:88; 20:131
- Και μη μειώνετε των ανθρώπων τα πράγματα, και μη σπέρνετε τη φθορά στη γη. (وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ) 11:85; 26:183
- Και ειρήνη σε αυτόν την ημέρα που γεννήθηκε, και την ημέρα που θα πεθάνει, και την ημέρα που θα αναστηθεί ζωντανός. (وَسَلَامٌ عَلَيْهِ يَوْمَ وُلِدَ وَيَوْمَ يَمُوتُ وَيَوْمَ يُبْعَثُ حَيًّا) 19:15; 19:33
- Λαέ μου! Δράστε ανάλογα με τη θέση σας, εγώ επίσης δρω, και σύντομα θα μάθετε ποιος. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ مَن) 6:135; 11:93
- Και δεν επιτρέπεται σε έναν Απόστολο να φέρει σημάδι παρά μόνο με την άδεια του Αλλάχ. (وَمَا كَانَ لِرَسُولٍ أَن يَأْتِيَ بِآيَةٍ إِلَّا بِإِذْنِ اللَّهِ) 13:38; 40:78
- Έπειτα, κάθε ψυχή θα ανταμειφθεί πλήρως για όσα έπραξε, και δεν θα αδικηθούν. (ثُمَّ تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:161
- Άντρας ή γυναίκα, και είναι πιστός, αυτοί θα μπουν στον Παράδεισο. (مِن ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَأُولَئِكَ يَدْخُلُونَ الْجَنَّةَ) 4:124; 40:40
- Δεν απέκτησε παιδί, και δεν έχει συνέταιρο στην κυριαρχία. (لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ) 17:111; 25:2
- Και όποιον ο Αλλάχ οδηγεί, αυτός είναι οδηγημένος· και όποιον παραπλανά. (وَمَن يَهْدِ اللَّهُ فَهُوَ الْمُهْتَدِ وَمَن يُضْلِلْ فَلَن تَجِدَ) 17:97; 18:17
- Κοίτα πώς σου φέρνουν παραδείγματα, και έτσι παραπλανήθηκαν, και δεν μπορούν να βρουν τον δρόμο. (انظُرْ كَيْفَ ضَرَبُوا لَكَ الْأَمْثَالَ فَضَلُّوا فَلَا يَسْتَطِيعُونَ سَبِيلًا) 17:48; 25:9
- Πες: "Φοβάμαι, αν παρακούσω τον Κύριό μου, την τιμωρία μιας μεγάλης ημέρας." (قُلْ إِنِّي أَخَافُ إِنْ عَصَيْتُ رَبِّي عَذَابَ يَوْمٍ عَظِيمٍ) 6:15; 39:13
- Τα αισχρά τους μέρη έγιναν φανερά σε αυτούς, και άρχισαν να καλύπτονται με φύλλα του Παραδείσου. (بَدَتْ لَهُمَا سَوْآتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ الْجَنَّةِ) 7:22; 20:121
- Και επικαλεστείτε όσους μπορείτε, εκτός από τον Αλλάχ, αν είστε ειλικρινείς. (وَادْعُوا مَنِ اسْتَطَعْتُم مِّن دُونِ اللَّهِ إِن كُنتُمْ صَادِقِينَ) 10:38; 11:13
