- Αυτά είναι από τις ειδήσεις του αόρατου που σου αποκαλύπτουμε· δεν τα γνώριζες. (ذَلِكَ مِنْ أَنْبَاءِ الْغَيْبِ نُوحِيهِ إِلَيْكَ وَمَا كُنتَ) 3:44; 11:49; 12:102
- Και όταν έρθει η προθεσμία τους, δεν μπορούν ούτε να την καθυστερήσουν ούτε να την επισπεύσουν. (فَإِذَا جَاءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ) 7:34; 10:49; 16:61
- Μην ακολουθείτε τα βήματα του σατανά, γιατί είναι φανερός εχθρός σας. (وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ) 2:168; 2:208; 6:142
- Και ανάμεσα στους ανθρώπους υπάρχουν εκείνοι που διαφωνούν για τον Αλλάχ χωρίς γνώση. (وَمِنَ النَّاسِ مَن يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ) 22:3; 22:8; 31:20
- Ο Αλλάχ το δίνει σε όποιον θέλει, και ο Αλλάχ είναι πλούσιος σε χάρη. (اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 57:21; 57:29; 62:4
- Κάθε ψυχή θα ανταμειφθεί πλήρως γι' αυτά που έπραξε, και δεν θα αδικηθούν. (تُوَفَّى كُلُّ نَفْسٍ مَّا كَسَبَتْ وَهُمْ لَا يُظْلَمُونَ) 2:281; 3:25; 3:161
- Μη σκοτώνετε την ψυχή που ο Αλλάχ απαγόρευσε, παρά μόνο δικαίως. (وَلَا تَقْتُلُوا النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ) 6:151; 17:33; 25:68
- Όταν αποφασίσει ένα θέμα, απλώς του λέει: Γίνε. (إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن) 3:47; 19:35; 40:68
- Μπείτε από τις πύλες της Κόλασης, όπου θα μείνετε αιώνια· και τι άσχημο κατάλυμα για τους υπερόπτες! (فَادْخُلُوا أَبْوَابَ جَهَنَّمَ خَالِدِينَ فِيهَا فَلَبِئْسَ مَثْوَى الْمُتَكَبِّرِينَ) 16:29; 39:72; 40:76
- Δεν είδες εκείνους στους οποίους δόθηκε μέρος της Γραφής; (أَلَمْ تَرَ إِلَى الَّذِينَ أُوتُوا نَصِيبًا مِّنَ الْكِتَابِ) 3:23; 4:44; 4:51
- Για αυτούς είναι κήποι κάτω από τους οποίους ρέουν ποτάμια, όπου θα μείνουν αιώνια. (لَهُمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:198; 5:119; 9:89
- Ω λαέ μου, δράστε σύμφωνα με τη θέση σας, κι εγώ θα δράσω, και σύντομα θα μάθετε. (يَاقَوْمِ اعْمَلُوا عَلَى مَكَانَتِكُمْ إِنِّي عَامِلٌ فَسَوْفَ تَعْلَمُونَ) 6:135; 11:93; 39:39
- Όποιος αντιτίθεται στον Αλλάχ και στον Αγγελιοφόρο Του, γι' αυτόν είναι η φωτιά της Κόλασης, όπου θα μείνει αιώνια. (اللَّهَ وَرَسُولَهُ فَأَنَّ لَهُ نَارَ جَهَنَّمَ خَالِدًا فِيهَا) 9:63; 72:23
- Βάλαμε επικαλύμματα στις καρδιές τους, για να μην το κατανοήσουν, και βάρος στα αυτιά τους. (عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا) 17:46; 18:57
- Σε όποια πόλη στείλαμε προειδοποιητή, οι εύποροι της είπαν: Εμείς. (فِي قَرْيَةٍ مِّن نَّذِيرٍ إِلَّا قَالَ مُتْرَفُوهَا إِنَّا) 34:34; 43:23
- Είπαν: Παρακάλεσε για μας τον Κύριό σου να μας ξεκαθαρίσει τι είναι. (قَالُوا ادْعُ لَنَا رَبَّكَ يُبَيِّن لَّنَا مَا هِيَ) 2:68; 2:70
- Θα πουν: Ο Αλλάχ. Πες: Δόξα στον Αλλάχ! Αλλά οι περισσότεροι από αυτούς. (لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا) 29:63; 31:25
- Και η απάντηση του λαού του ήταν μόνο ότι είπαν: Βγάλτε τους έξω. (وَمَا كَانَ جَوَابَ قَوْمِهِ إِلَّا أَن قَالُوا أَخْرِجُوهُم) 7:82; 27:56
- Κάτω από τους οποίους ρέουν ποτάμια, όπου θα μείνουν αιώνια· αυτή είναι η μεγάλη επιτυχία. (تَحْتَهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ذَلِكَ الْفَوْزُ الْعَظِيمُ) 9:100; 64:9
- Αυτοί βρίσκονται σε οδηγία από τον Κύριό τους, και αυτοί είναι οι επιτυχημένοι. (أُولَئِكَ عَلَى هُدًى مِّن رَّبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ) 2:5; 31:5
- Εκείνον που θα τον βρει τιμωρία που τον εξευτελίζει και θα τον βρει αιώνια τιμωρία. (مَن يَأْتِيهِ عَذَابٌ يُخْزِيهِ وَيَحِلُّ عَلَيْهِ عَذَابٌ مُّقِيمٌ) 11:39; 39:40
- Περιηγηθείτε στη γη και δείτε ποιο ήταν το τέλος εκείνων που αρνήθηκαν. (فَسِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ الْمُكَذِّبِينَ) 3:137; 16:36
- Δεν θα το επιθυμήσουν ποτέ, λόγω αυτών που έστειλαν τα χέρια τους, και ο Αλλάχ γνωρίζει τους άδικους. (يَتَمَنَّوْهُ أَبَدًا بِمَا قَدَّمَتْ أَيْدِيهِمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ) 2:95; 62:7
- Αυτός γνωρίζει καλύτερα ποιος πλανήθηκε από τον δρόμο Του, και Αυτός γνωρίζει καλύτερα. (هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ أَعْلَمُ) 53:30; 68:7
- Αληθινά, ο Αλλάχ είναι ο Κύριός μου και ο Κύριός σας, γι' αυτό λατρεύστε Τον· αυτός είναι ο ευθύς δρόμος. (إِنَّ اللَّهَ رَبِّي وَرَبُّكُمْ فَاعْبُدُوهُ هَذَا صِرَاطٌ مُّسْتَقِيمٌ) 3:51; 19:36
- Είναι γεμάτος χάρη για τους ανθρώπους, αλλά οι περισσότεροι από αυτούς δεν ευγνωμονούν. (لَذُو فَضْلٍ عَلَى النَّاسِ وَلَكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ) 10:60; 27:73
- Τους ουρανούς και τη γη και όσα είναι μεταξύ τους δημιουργήσαμε μόνο με αλήθεια και για καθορισμένο χρόνο. (السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ وَأَجَلٍ مُّسَمًّى) 30:8; 46:3
- Άφησέ τους να βυθιστούν (στη ματαιότητα) και να παίζουν, μέχρι να συναντήσουν την Ημέρα τους που τους υποσχέθηκαν. (فَذَرْهُمْ يَخُوضُوا وَيَلْعَبُوا حَتَّى يُلَاقُوا يَوْمَهُمُ الَّذِي يُوعَدُونَ) 43:83; 70:42
- Όταν συναντούν αυτούς που πίστεψαν, λένε: Πιστέψαμε, και όταν μένουν μόνοι. (وَإِذَا لَقُوا الَّذِينَ آمَنُوا قَالُوا آمَنَّا وَإِذَا خَلَوْا) 2:14; 2:76
- Τηρούν την Τορά και το Ευαγγέλιο και όσα τους στάλθηκαν από τον Κύριό τους. (أَقَامُوا التَّوْرَاةَ وَالْإِنجِيلَ وَمَا أُنزِلَ إِلَيْهِم مِّن رَّبِّهِمْ) 5:66; 5:68
- Γνωρίζει τι είναι μπροστά τους και τι πίσω τους, και αυτοί δεν το περιβάλλουν με τη γνώση τους. (يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ) 2:255; 20:110
- Και Αυτός είναι που δημιούργησε τους ουρανούς και τη γη σε έξι ημέρες. (وَهُوَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ) 11:7; 57:4
- Σε αυτό υπάρχει σημάδι για εσάς, αν είστε πιστοί. (إِنَّ فِي ذَلِكَ لَآيَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ) 2:248; 3:49
- Τι εμπόδισε τους ανθρώπους να πιστέψουν όταν τους ήρθε η οδηγία; (وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَى) 17:94; 18:55
- Και έκαναν στον Αλλάχ εταίρους, για να ξεστρατίζουν από τον δρόμο Του. Πες: Απολαύστε. (وَجَعَلُوا لِلَّهِ أَندَادًا لِّيُضِلُّوا عَن سَبِيلِهِ قُلْ تَمَتَّعُوا) 14:30; 39:8
- Και απόρησαν που ήρθε σε αυτούς προειδοποιητής από ανάμεσά τους, και οι άπιστοι είπαν: Αυτός. (وَعَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ وَقَالَ الْكَافِرُونَ هَذَا) 38:4; 50:2
- Αληθινά, ο Κύριός σου γνωρίζει καλύτερα ποιος πλανήθηκε από τον δρόμο Του. (إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ) 53:30; 68:7
- Όπως εκείνος που ξοδεύει την περιουσία του για επίδειξη στους ανθρώπους και δεν πιστεύει στον Αλλάχ. (كَالَّذِي يُنفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ) 2:264; 4:38
- Ξοδέψτε από όσα σας δώσαμε, πριν έρθει. (أَنفِقُوا مِمَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ) 2:254; 63:10
- Σας υπέταξε ό,τι υπάρχει στους ουρανούς και στη γη. (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 31:20; 45:13
- Κι εμείς είμαστε σε αμφιβολία γι' αυτό που μας καλείτε. (وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ) 11:62; 14:9
- Αληθινά, ο Κύριός σου αυξάνει τα προς το ζην σε όποιον θέλει και τα περιορίζει. Αληθινά, Αυτός. (إِنَّ رَبَّكَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ وَيَقْدِرُ إِنَّهُ) 17:30; 34:36
- Ο Κύριος των ουρανών και της γης και όσων είναι μεταξύ τους, αν είστε βέβαιοι. (رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا إِن كُنتُم مُّوقِنِينَ) 26:24; 44:7
- Πιστέψαμε στον Αλλάχ και σε όσα στάλθηκαν σε εμάς και σε όσα στάλθηκαν σε. (آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى) 2:136; 3:199
- Και εκείνους που αδίκησαν, τους βρήκε η φωνή και έμειναν γονατιστοί στα σπίτια τους. (وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَةُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ) 11:67; 11:94
- Δεν υπάρχει αμαρτία σε εσάς για ό,τι κάνουν σε σχέση με τον εαυτό τους. (فَلَا جُنَاحَ عَلَيْكُمْ فِيمَا فَعَلْنَ فِي أَنفُسِهِنَّ) 2:234; 2:240
- Ο Κύριός σου γνωρίζει καλύτερα ποιος πλανήθηκε από τον δρόμο Του, και Αυτός. (رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِ وَهُوَ) 53:30; 68:7
- Με το Πνεύμα (αποκάλυψη) από την εντολή Του, σε όποιον θέλει από τους δούλους Του. (بِالرُّوحِ مِنْ أَمْرِهِ عَلَى مَن يَشَاءُ مِنْ عِبَادِهِ) 16:2; 40:15
- Και δώσαμε στον Ιησού, τον γιο της Μαρίας, τα ξεκάθαρα σημάδια και τον ενισχύσαμε με το Άγιο Πνεύμα. (وَآتَيْنَا عِيسَى ابْنَ مَرْيَمَ الْبَيِّنَاتِ وَأَيَّدْنَاهُ بِرُوحِ الْقُدُسِ) 2:87; 2:253
- Για να κρίνει μεταξύ τους την Ημέρα της Ανάστασης γι' αυτά που διαφωνούσαν. (لَيَحْكُمُ بَيْنَهُمْ يَوْمَ الْقِيَامَةِ فِيمَا كَانُوا فِيهِ) 16:124; 22:69
- Και αναποδογυρίσαμε την πόλη και ρίξαμε πάνω τους πέτρες από πηλό. (جَعَلْنَا عَالِيَهَا سَافِلَهَا وَأَمْطَرْنَا عَلَيْهَا حِجَارَةً مِّن سِجِّيلٍ) 11:82; 15:74
- Είναι το ίδιο γι' αυτούς, είτε τους προειδοποιήσεις είτε όχι, δεν θα πιστέψουν. (سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ) 2:6; 36:10
- Εκτός από τους ανθρώπους, γι' αυτό επιθυμήστε τον θάνατο, αν είστε αληθινοί. (مِّن دُونِ النَّاسِ فَتَمَنَّوُا الْمَوْتَ إِن كُنتُمْ صَادِقِينَ) 2:94; 62:6
- Τον Αλλάχ, δεν έχετε άλλο θεό εκτός από Αυτόν. Δεν φοβάστε; (اللَّهَ مَا لَكُم مِّنْ إِلَهٍ غَيْرُهُ أَفَلَا تَتَّقُونَ) 23:23; 23:32
- Είτε σου δείξουμε μέρος από αυτό που τους υποσχεθήκαμε, είτε σε πάρουμε, σε εμάς είναι η επιστροφή τους. (وَإِمَّا نُرِيَنَّكَ بَعْضَ الَّذِي نَعِدُهُمْ أَوْ نَتَوَفَّيَنَّكَ فَإِلَيْنَا) 10:46; 40:77
- Είπαν: Όταν πεθάνουμε και γίνουμε χώμα και κόκαλα, θα αναστηθούμε; (قَالُوا أَإِذَا مِتْنَا وَكُنَّا تُرَابًا وَعِظَامًا أَإِنَّا لَمَبْعُوثُونَ) 23:82; 56:47
- Η χάρη βρίσκεται στο χέρι του Αλλάχ· τη δίνει σε όποιον θέλει. Και ο Αλλάχ. (إِنَّ الْفَضْلَ بِيَدِ اللَّهِ يُؤْتِيهِ مَن يَشَاءُ وَاللَّهُ) 3:73; 57:29
- Και θα επιστρέψετε σε Αυτόν που γνωρίζει το αόρατο και το φανερό, και θα σας ενημερώσει για όσα κάνατε. (إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ) 9:105; 62:8
- Εσείς που πιστέψατε, θυμηθείτε τη χάρη του Αλλάχ προς εσάς, όταν. (يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَتَ اللَّهِ عَلَيْكُمْ إِذْ) 5:11; 33:9
- Και πριν από εσένα δεν στείλαμε παρά άνδρες στους οποίους δίναμε αποκάλυψη. (وَمَا أَرْسَلْنَا مِن قَبْلِكَ إِلَّا رِجَالًا نُّوحِي إِلَيْهِم) 12:109; 16:43
- Θα συγχωρήσει τις αμαρτίες του και θα τον εισάγει σε κήπους κάτω από τους οποίους ρέουν ποτάμια. (يُكَفِّرْ عَنْهُ سَيِّئَاتِهِ وَيُدْخِلْهُ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا) 64:9; 66:8
- Όποιος είναι άρρωστος ή σε ταξίδι, τότε (να νηστέψει) άλλες ημέρες. (مَّرِيضًا أَوْ عَلَى سَفَرٍ فَعِدَّةٌ مِّنْ أَيَّامٍ أُخَرَ) 2:184; 2:185
- Δεν ακολουθούν παρά την εικασία, και δεν κάνουν παρά υποθέσεις. (إِن يَتَّبِعُونَ إِلَّا الظَّنَّ وَإِنْ هُمْ إِلَّا يَخْرُصُونَ) 6:116; 10:66
- Ένα καλό παράδειγμα για όποιον ελπίζει στον Αλλάχ και την Έσχατη Ημέρα. (أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ) 33:21; 60:6
- Και δεν δημιουργήσαμε τους ουρανούς και τη γη και όσα είναι μεταξύ τους, παρά με αλήθεια. (وَمَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ وَمَا بَيْنَهُمَا إِلَّا بِالْحَقِّ) 15:85; 46:3
- Βάλε το χέρι σου στον κόρφο σου, θα βγει λευκό χωρίς βλάβη. (يَدَكَ فِي جَيْبِكَ تَخْرُجْ بَيْضَاءَ مِنْ غَيْرِ سُوءٍ) 27:12; 28:32
- Εκλέγει με το έλεός Του όποιον θέλει, και ο Αλλάχ είναι πλούσιος σε χάρη. (يَخْتَصُّ بِرَحْمَتِهِ مَن يَشَاءُ وَاللَّهُ ذُو الْفَضْلِ الْعَظِيمِ) 2:105; 3:74
- Δεν γνωρίζεις ότι ο Αλλάχ έχει την εξουσία των ουρανών και της γης; (أَلَمْ تَعْلَمْ أَنَّ اللَّهَ لَهُ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ) 2:107; 5:40
- Ό,τι καλό κι αν στείλετε μπροστά για τον εαυτό σας, θα το βρείτε κοντά στον Αλλάχ. (وَمَا تُقَدِّمُوا لِأَنفُسِكُم مِّنْ خَيْرٍ تَجِدُوهُ عِندَ اللَّهِ) 2:110; 73:20
- Και όπου κι αν βγεις, στρέψε το πρόσωπό σου προς το Ιερό Τέμενος. (وَمِنْ حَيْثُ خَرَجْتَ فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ) 2:149; 2:150
- Όσοι ήταν πριν από εσάς, και δεν θα βρεις αλλαγή στον νόμο του Αλλάχ. (خَلَوْا مِن قَبْلُ وَلَن تَجِدَ لِسُنَّةِ اللَّهِ تَبْدِيلًا) 33:62; 48:23
- Εκείνου που ανήκει ό,τι υπάρχει στους ουρανούς και στη γη. (الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ) 34:1; 42:53
- Καμία γυναίκα δεν μένει έγκυος ούτε γεννά, παρά με τη γνώση Του. (وَمَا تَحْمِلُ مِنْ أُنثَى وَلَا تَضَعُ إِلَّا بِعِلْمِهِ) 35:11; 41:47
- Υπέταξε τη νύχτα, τον ήλιο και το φεγγάρι· το καθένα κινείται μέχρι καθορισμένου χρόνου. (اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى) 35:13; 39:5
- Κάτω από τους οποίους ρέουν ποτάμια, όπου θα μείνουν αιώνια, και αυτή είναι η ανταμοιβή. (تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ) 5:85; 20:76
- Είπε: Όχι, οι ψυχές σας σας παρότρυναν σε κάτι· υπομονή λοιπόν. (قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ) 12:18; 12:83
- Ό,τι υπάρχει στους ουρανούς και στη γη, και ότι ο Αλλάχ. (مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَنَّ اللَّهَ) 5:97; 22:64
- Και δεν τους ήρθε αγγελιοφόρος, χωρίς να τον κοροϊδέψουν. (وَمَا يَأْتِيهِم مِّن رَّسُولٍ إِلَّا كَانُوا بِهِ يَسْتَهْزِئُونَ) 15:11; 36:30
- Είπαν: Ω Μωυσή, είτε εσύ θα ρίξεις, είτε εμείς θα ρίξουμε; (قَالُوا يَامُوسَى إِمَّا أَن تُلْقِيَ وَإِمَّا أَن نَّكُونَ) 7:115; 20:65
- Αυτός σας θανατώνει, και κάποιοι από εσάς επιστρέφονται στην πιο αδύναμη ηλικία, ώστε. (يَتَوَفَّاكُمْ وَمِنكُم مَّن يُرَدُّ إِلَى أَرْذَلِ الْعُمُرِ لِكَيْ) 16:70; 22:5
- Για αυτούς είναι κήποι κάτω από τους οποίους ρέουν ποτάμια, όπου θα μείνουν αιώνια. (رَبِّهِمْ جَنَّاتٌ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 3:15; 3:136
- Και βάλαμε επικαλύμματα στις καρδιές τους, για να μην το κατανοήσουν, και βάρος στα αυτιά τους. (وَجَعَلْنَا عَلَى قُلُوبِهِمْ أَكِنَّةً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ) 17:46; 18:57
- Η υπόσχεση του Αλλάχ είναι αληθινή, αλλά οι περισσότεροι από αυτούς δεν γνωρίζουν. (إِنَّ وَعْدَ اللَّهِ حَقٌّ وَلَكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ) 10:55; 28:13
- Αυτό γιατί αντιστάθηκαν στον Αλλάχ και στον Αγγελιοφόρο Του· και όποιος αντιστέκεται στον Αλλάχ. (ذَلِكَ بِأَنَّهُمْ شَاقُّوا اللَّهَ وَرَسُولَهُ وَمَن يُشَاقِقِ اللَّهَ) 8:13; 59:4
- Και την Ημέρα που θα τους καλέσει και θα πει: Πού είναι οι εταίροι Μου που υποστηρίζατε; (وَيَوْمَ يُنَادِيهِمْ فَيَقُولُ أَيْنَ شُرَكَائِيَ الَّذِينَ كُنتُمْ تَزْعُمُونَ) 28:62; 28:74
- Δεν είδαν ότι ο Αλλάχ, που δημιούργησε τους ουρανούς και τη γη, μπορεί να δημιουργήσει όμοιούς τους; (أَوَلَمْ يَرَوْا أَنَّ اللَّهَ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ) 17:99; 46:33
- (Αυτός) που σας έπλασε από χώμα, μετά από σταγόνα, μετά. (بِالَّذِي خَلَقَكَ مِن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ) 18:37; 40:67
- Θα έλεγαν: Κύριέ μας, γιατί δεν μας έστειλες έναν αγγελιοφόρο, για να ακολουθήσουμε τα σημάδια Σου; (لَقَالُوا رَبَّنَا لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ) 20:134; 28:47
- Μετά η επιστροφή τους θα είναι στον Κύριό τους, και θα τους ενημερώσει για όσα έκαναν. (ثُمَّ إِلَى رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا يَعْمَلُونَ) 6:108; 39:7
- Δεν έχουν γνώση γι' αυτό· ακολουθούν μόνο εικασίες. (مَّا لَهُم بِذَلِكَ مِنْ عِلْمٍ إِنْ هُمْ إِلَّا) 43:20; 45:24
- Βρήκαμε τους πατέρες μας σε μια θρησκεία, κι εμείς ακολουθούμε τα βήματά τους. (إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِم) 43:22; 43:23
- Εκείνοι στους οποίους δόθηκε η Γραφή, δεν διαφώνησαν παρά μόνο αφού τους ήρθε η γνώση. (الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَهُمُ) 3:19; 98:4
- Και όταν ο Αβραάμ είπε: Κύριέ μου, κάνε αυτή την πόλη ασφαλή. (وَإِذْ قَالَ إِبْرَاهِيمُ رَبِّ اجْعَلْ هَذَا بَلَدًا آمِنًا) 2:126; 14:35
- Σας έδωσε την ακοή, την όραση και τις καρδιές· λίγο ευγνωμονείτε. (وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَ قَلِيلًا مَّا تَشْكُرُونَ) 32:9; 67:23
- Εκείνοι που διαφωνούν για τα σημάδια του Αλλάχ, χωρίς εξουσία που τους ήρθε. (الَّذِينَ يُجَادِلُونَ فِي آيَاتِ اللَّهِ بِغَيْرِ سُلْطَانٍ أَتَاهُمْ) 40:35; 40:56
- Ακολουθήστε τη θρησκεία του Αβραάμ, του ορθόδοξου, και δεν ήταν από τους ειδωλολάτρες. (فَاتَّبِعُوا مِلَّةَ إِبْرَاهِيمَ حَنِيفًا وَمَا كَانَ مِنَ الْمُشْرِكِينَ) 3:95; 16:123
- Και όταν σας σώσαμε από την οικογένεια του Φαραώ, που σας υπέβαλαν σε φρικτό βασανιστήριο. (وَإِذْ أَنجَيْنَاكُم مِّنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذَابِ) 7:141; 14:6
- Αυτή είναι η ορθή θρησκεία, αλλά οι περισσότεροι άνθρωποι δεν γνωρίζουν. (ذَلِكَ الدِّينُ الْقَيِّمُ وَلَكِنَّ أَكْثَرَ النَّاسِ لَا يَعْلَمُونَ) 12:40; 30:30
- Δεν βλέπεις ότι ο Αλλάχ σας υπέταξε όσα υπάρχουν στους. (أَلَمْ تَرَ أَنَّ اللَّهَ سَخَّرَ لَكُم مَّا فِي) 22:65; 31:20
- Οι άπιστοι θα έλεγαν: Αυτό δεν είναι παρά φανερή μαγεία. (لَقَالَ الَّذِينَ كَفَرُوا إِنْ هَذَا إِلَّا سِحْرٌ مُّبِينٌ) 6:7; 11:7
- Και όταν τους αναγιγνώσκονται τα ξεκάθαρα σημάδια μας, οι άπιστοι λένε. (وَإِذَا تُتْلَى عَلَيْهِمْ آيَاتُنَا بَيِّنَاتٍ قَالَ الَّذِينَ كَفَرُوا) 19:73; 46:7
- Κήποι της Αϊώνιας Κατοικίας, κάτω από τους οποίους ρέουν ποτάμια, όπου θα μείνουν αιώνια. (جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا) 20:76; 98:8
- Δημιουργεί ό,τι θέλει· ο Αλλάχ είναι Παντοδύναμος. (مَا يَشَاءُ إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ) 24:45; 35:1
- Για να σας συγχωρήσει τις αμαρτίες σας και να σας αναβάλει μέχρι καθορισμένου χρόνου. (لِيَغْفِرَ لَكُم مِّن ذُنُوبِكُمْ وَيُؤَخِّرَكُمْ إِلَى أَجَلٍ مُّسَمًّى) 14:10; 71:4
- Θέλετε να μας αποτρέψετε από αυτό που λάτρευαν οι πατέρες μας; (تُرِيدُونَ أَن تَصُدُّونَا عَمَّا كَانَ يَعْبُدُ آبَاؤُنَا) 14:10; 34:43
- Και όταν ο Κύριός σου είπε στους αγγέλους: Θα δημιουργήσω άνθρωπο από πηλό. (وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي خَالِقٌ بَشَرًا مِّن) 15:28; 38:71
- Και Αυτός είναι που στέλνει τους ανέμους ως μηνυτές χαράς μπροστά από το έλεός Του. (وَهُوَ الَّذِي يُرْسِلُ الرِّيَاحَ بُشْرًا بَيْنَ يَدَيْ رَحْمَتِهِ) 7:57; 25:48
- Πες: Περιηγηθείτε στη γη και δείτε ποιο ήταν το τέλος. (قُلْ سِيرُوا فِي الْأَرْضِ فَانظُرُوا كَيْفَ كَانَ عَاقِبَةُ) 27:69; 30:42
- Στη δημιουργία των ουρανών και της γης, και στην εναλλαγή νύχτας και ημέρας (είναι σημάδια). (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ) 2:164; 3:190
- Ποιος θα δανείσει στον Αλλάχ ένα καλό δάνειο, για να του το πολλαπλασιάσει; (مَّن ذَا الَّذِي يُقْرِضُ اللَّهَ قَرْضًا حَسَنًا فَيُضَاعِفَهُ) 2:245; 57:11
- Κρίνε ανάμεσά τους σύμφωνα με όσα έστειλε ο Αλλάχ, και μην ακολουθείς τις επιθυμίες τους. (فَاحْكُم بَيْنَهُم بِمَا أَنزَلَ اللَّهُ وَلَا تَتَّبِعْ أَهْوَاءَهُمْ) 5:48; 5:49
- Μήπως περιμένουν τίποτα άλλο παρά να τους έρθουν οι άγγελοι, ή να έρθει η εντολή του Κυρίου σου; (هَلْ يَنظُرُونَ إِلَّا أَن تَأْتِيَهُمُ الْمَلَائِكَةُ أَوْ يَأْتِيَ) 6:158; 16:33
- Αληθινά, εκείνοι που επινοούν ψέματα εναντίον του Αλλάχ, δεν θα επιτύχουν. (إِنَّ الَّذِينَ يَفْتَرُونَ عَلَى اللَّهِ الْكَذِبَ لَا يُفْلِحُونَ) 10:69; 16:116
- Όπως η συνήθεια της οικογένειας του Φαραώ και εκείνων πριν από αυτούς· αρνήθηκαν τα σημάδια μας. (كَدَأْبِ آلِ فِرْعَوْنَ وَالَّذِينَ مِن قَبْلِهِمْ كَذَّبُوا بِآيَاتِنَا) 3:11; 8:54
- Και φέρνει χαρμόσυνα νέα στους πιστούς που κάνουν καλά έργα, ότι τους αξίζει ανταμοιβή. (وَيُبَشِّرُ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّالِحَاتِ أَنَّ لَهُمْ أَجْرًا) 17:9; 18:2
- Ο Αλλάχ αυξάνει τα προς το ζην σε όποιον θέλει από τους δούλους Του και τα περιορίζει. (اللَّهَ يَبْسُطُ الرِّزْقَ لِمَن يَشَاءُ مِنْ عِبَادِهِ وَيَقْدِرُ) 28:82; 29:62
- Και θα επιστρέψετε σε Αυτόν που γνωρίζει το αόρατο και το φανερό, και θα σας ενημερώσει για όσα κάνατε. (وَسَتُرَدُّونَ إِلَى عَالِمِ الْغَيْبِ وَالشَّهَادَةِ فَيُنَبِّئُكُم بِمَا كُنتُمْ) 9:105; 62:8
- Και οι συγγενείς είναι πιο κοντά μεταξύ τους, σύμφωνα με τη Γραφή του Αλλάχ. (وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَى بِبَعْضٍ فِي كِتَابِ اللَّهِ) 8:75; 33:6
cmds - Commands, Exhortations, Prohibitions, Instructions
- fard / wajib (فرض / واجب) — υποχρεωτικό (πρέπει να γίνει· αμαρτία να παραλειφθεί)
- mustahabb / mandub (مستحب / مندوب) — συνιστώμενο (ανταμείβεται αν γίνει, όχι αμαρτία αν παραλειφθεί)
- mubah (مباح) — ουδέτερο / επιτρεπτό (ούτε ανταμοιβή ούτε αμαρτία)
- makruh (مكروه) — απεχθές / αποδοκιμαστέο (αποθαρρύνεται, αλλά όχι αμαρτία αν γίνει)
- haram (حرام) — απαγορευμένο (αμαρτία να γίνει)
- halal (حلال, επιτρεπτό / νόμιμο) — περιλαμβάνει τόσο το mubah όσο και το mustahabb — οτιδήποτε δεν απαγορεύεται
- Λατρεύετε μόνο τον Αλλάχ και ζητάτε τη βοήθεια/υποστήριξή Του. 1:5
- Λατρεύετε μόνο τον Αλλάχ. 2:21
- Μην αποδίδετε συντρόφους στον Αλλάχ. 2:22
- Ο Αλλάχ είναι Αυτός που συγχωρεί (δέχεται τη μετάνοια), δέχθηκε τη μετάνοια του Αδάμ (ειρήνη σε αυτόν). 2:37
- Μην αναμιγνύετε την αλήθεια με το ψέμα και μην κρύβετε την αλήθεια. 2:42
- Εκτελείτε την προσευχή (τις καθημερινές προσευχές) και δίνετε τη ζακάτ (ελεημοσύνη). 2:43
- Προστάξτε τους άλλους να κάνουν το καλό αφού πρώτα το εφαρμόσετε μόνοι σας. 2:44
- Ζητήστε τη βοήθεια του Αλλάχ σε όλες σας τις υποθέσεις. 2:45
- Μην εμπλέκεστε σε διαφθορά και μην τη διαδίδετε. 2:60
- Μην εμποδίζετε τους ανθρώπους να πηγαίνουν στους τόπους λατρείας. 2:114
- Σεβαστείτε την ιερότητα του τζαμιού. Διατηρείτε τους χώρους προσευχής σας καθαρούς και αγνούς. 2:125
- Θυμάστε τον Αλλάχ (με προσευχή, δοξολογία κ.λπ.) και Αυτός θα σας θυμάται, και να είστε ευγνώμονες σε Αυτόν. 2:152
- Να είστε υπομονετικοί στις αντιξοότητες. 2:153
- Μην ακολουθείτε τα βήματα του Σατανά, ο οποίος είναι φανερός εχθρός. 2:168
- Μην ακολουθείτε κανέναν τυφλά. 2:170
- Φυλάξτε και εκπληρώστε όλες τις παρακαταθήκες. Εκπληρώστε τα θρησκευτικά σας καθήκοντα με ειλικρίνεια. Εκπληρώστε τους όρκους και τις συνθήκες σας. Τηρείτε τις υποσχέσεις, ειδικά αυτές που δώσατε στον Αλλάχ. Υποστηρίξτε τους απόρους και ανακουφίστε τις δυσκολίες. Αποφύγετε την τέλεση αμαρτιών που οδηγούν σε απώλεια της θεϊκής εύνοιας. Μην αφήνετε την υπερηφάνεια να σας οδηγεί σε αδικία. 2:177
- Στην κιζάς (ο νόμος της ισότητας στην τιμωρία) υπάρχει (σωτηρία) ζωής για εσάς. 2:179
- Νηστεύετε κατά τον μήνα Ραμαδάν. Τηρήστε την προδιαγεγραμμένη νηστεία για να γίνετε οι Μουττακούν (οι ευσεβείς). 2:183
- Σεβαστείτε το Κοράνι ως την απόλυτη πηγή καθοδήγησης. 2:185
- Μην κατατρώγετε την περιουσία του άλλου άδικα και μην δίνετε δωροδοκίες στους δικαστές (πριν παρουσιάσετε τις υποθέσεις σας). 2:188
- Μην καταπιέζετε τους άλλους, με λόγια ή με έργα. Μην πολεμάτε ποτέ ως επιτιθέμενοι, αλλά μόνο για άμυνα. 2:190
- Προστατεύετε τα ορφανά. Όσον αφορά τα ορφανά, να διαχειρίζεστε την περιουσία τους τίμια και να μην την κατατρώγετε. 2:220
- Μετανοήστε και ζητήστε τη συγχώρεση του Αλλάχ. Μην έχετε σεξουαλική επαφή κατά την περίοδο της εμμήνου ρύσεως. Διατηρήστε την αγνότητα (τόσο σωματική όσο και πνευματική). 2:222
- Εκπληρώστε τις ευθύνες σας απέναντι στην οικογένειά σας. 2:233
- Επιλέξτε ηγέτες με βάση την αξία τους. 2:247
- Δεν υπάρχει εξαναγκασμός στη θρησκεία. 2:256
- Ξοδέψτε πλούτο σε φιλανθρωπία. Να είστε φιλάνθρωποι και σε πλούτο και σε χρόνο. 2:261
- Μην ακυρώνετε τη φιλανθρωπία σας καυχώμενοι για τη γενναιοδωρία σας. 2:264
- Ο Σατανάς σας απειλεί με φτώχεια και σας προστάζει να διαπράττετε αισχρότητες (κακές πράξεις, παράνομες σεξουαλικές σχέσεις, αμαρτίες). 2:268
- Αναζητήστε τους απόρους και βοηθήστε τους. 2:273
- Μην εμπλέκεστε σε τοκογλυφία και τόκους. Μην καταναλώνετε περιουσία που φέρει τόκους. Μην τρώτε ρίμπα (τοκογλυφία). 2:275
- Δώστε περισσότερο χρόνο στον οφειλέτη να αποπληρώσει αν βρίσκεται σε δυσκολία. 2:280
- Κρατήστε το λόγο σας στις εμπορικές συναλλαγές. Να είστε αληθείς στις οικονομικές σας υποθέσεις. Να ενεργείτε με ακεραιότητα σε όλες σας τις δεσμεύσεις. Όταν συνάπτετε χρέος για καθορισμένο χρονικό διάστημα, καταγράψτε το. Παίρνετε μάρτυρες όποτε συνάπτετε εμπορική σύμβαση. 2:282
- Φυλάξτε και εκπληρώστε όλες τις παρακαταθήκες. 2:283
- Πιστέψτε στις αποκαλυφθείσες Γραφές και σε όλους τους Προφήτες. 2:285
- Ο Αλλάχ δεν επιβαρύνει κανέναν πέρα από τις δυνατότητές του. Θα λάβει ανταμοιβή για το καλό που απέκτησε και τιμωρία για το κακό που απέκτησε. Ο Θεός δεν επιβαρύνει τον άνθρωπο πέρα από τις δυνατότητές του· ούτε εμείς πρέπει να το κάνουμε. Εμπιστευτείτε το σχέδιο του Αλλάχ ακόμα και στις δυσκολίες. 2:286
- Όποιος εκπληρώνει τις υποσχέσεις του και φοβάται τον Αλλάχ, τότε ο Αλλάχ αγαπά τους ευσεβείς. 3:76
- Εκτελέστε το χατζ (το προσκύνημα) αν έχετε τη δυνατότητα. 3:97
- Μην διχάζεστε. 3:103
- Προστάξτε το καλό και απαγορεύστε το κακό. Ενθαρρύνετε τη δικαιοσύνη στην κοινότητά σας. Καλέστε τους άλλους στην ανάμνηση του Αλλάχ. 3:104
- Οι πιστοί πρέπει να εμπιστεύονται τον Αλλάχ. 3:122
- Μην τρώτε ρίμπα (τοκογλυφία). 3:130
- Υπακούτε στον Αλλάχ και στον Αγγελιαφόρο Του για να λάβετε έλεος. 3:132
- Ο Αλλάχ αγαπά αυτούς που ξοδεύουν (για την υπόθεση του Αλλάχ — φιλανθρωπικά έργα, ελεημοσύνη, κ.λπ.) στην ευημερία και στη δυσχέρεια, που συγκρατούν τον θυμό τους και που συγχωρούν τους ανθρώπους. 3:134
- Συγκρατήστε τον θυμό σας. Ελέγξτε τον θυμό σας. 3:134
- Συγχωρήστε και συγχωρέστε τα λάθη των άλλων. 3:135
- Μην είστε αγενείς στον λόγο. Να είστε υπομονετικοί με εκείνους που διαφέρουν από εσάς. 3:159
- Αν ο Αλλάχ σας βοηθήσει, κανείς δεν μπορεί να σας νικήσει· και αν σας εγκαταλείψει, ποιος είναι αυτός που μετά από Αυτόν μπορεί να σας βοηθήσει; 3:160
- Κάθε ψυχή θα γευτεί τον θάνατο. Και μόνο την Ημέρα της Ανάστασης θα λάβετε ολόκληρη την ανταμοιβή σας. 3:185
- Σκεφτείτε βαθιά τα θαύματα της φύσης και τη δημιουργία αυτού του σύμπαντος. Να ξέρετε ότι ο Θεός δημιούργησε το σύμπαν με νόημα και σκοπό. 3:191
- Οι άνδρες και οι γυναίκες έχουν ίση ανταμοιβή για τις πράξεις τους. 3:195
- Για εκείνους που φοβούνται τον Κύριό τους, υπάρχουν Κήποι (στον Παράδεισο) από κάτω από τους οποίους ρέουν ποταμοί· εκεί θα κατοικούν για πάντα, ως φιλοξενία από τον Αλλάχ. 3:198
- Να επιδιώκετε πάντα την ευαρέσκεια του Αλλάχ σε κάθε πράξη. 3:200
- Να είστε ευσεβείς απέναντι στον Κύριό σας, να Τον φοβάστε και (μην κόβετε) τους συγγενικούς δεσμούς. 4:1
- Δώστε στα ορφανά την περιουσία τους και μην ανταλλάσσετε (τα δικά σας κακά) με τα (δικά τους καλά)· και μην κατατρώγετε την περιουσία τους (προσθέτοντάς την στη δική σας). 4:2
- Δώστε στις γυναίκες (που παντρεύεστε) τον μάχρ τους (την υποχρεωτική προίκα που ο σύζυγος δίνει στη σύζυγό του κατά τον γάμο) με καλή καρδιά. 4:4
- Προστατέψτε τα δικαιώματα των ορφανών. 4:6
- Η περιουσία του νεκρού πρέπει να μοιραστεί μεταξύ των μελών της οικογένειάς του. Οι γυναίκες έχουν δικαίωμα κληρονομιάς. 4:7
- Μην κατατρώγετε την περιουσία των ορφανών άδικα. 4:10
- Υπακούστε στις εντολές σχετικά με την κληρονομιά. 4:11
- Απαγορεύεται να κληρονομείτε γυναίκες παρά τη θέλησή τους και δεν πρέπει να τις μεταχειρίζεστε σκληρά. Ζήστε μαζί τους (τις συζύγους) με τιμή. Σεβαστείτε και τηρήστε τα δικαιώματα των γυναικών. Συμπεριφέρεστε στη σύζυγό σας με καλοσύνη και συμπόνια. Συμπεριφέρεστε στις γυναίκες με τιμή και δικαιοσύνη. 4:19
- Μην παντρεύεστε εκείνους που είναι εξ αίματος συγγενείς σας. 4:23
- Μην σκοτώνετε ο ένας τον άλλον. Ο Αλλάχ είναι σπλαχνικός απέναντί σας. Μην κατατρώγετε την περιουσία του άλλου άδικα. 4:29
- Αν αποφεύγετε τις μεγάλες αμαρτίες που απαγορεύονται, ο Αλλάχ θα σας συγχωρήσει τις (μικρές) αμαρτίες σας και θα σας εισαγάγει σε ευγενή είσοδο (τον Παράδεισο). 4:31
- Μην επιθυμείτε αυτά με τα οποία ο Αλλάχ έκανε κάποιους από εσάς να υπερέχουν άλλων. Αποφύγετε τον φθόνο και τη ζήλια. 4:32
- Οι άνδρες είναι προστάτες και φύλακες των γυναικών, επειδή ο Αλλάχ έκανε κάποιους να υπερέχουν άλλων, και επειδή ξοδεύουν από τα μέσα τους (για τη συντήρησή τους). Ο άνδρας είναι ο προστάτης και υποστηρικτής της οικογένειας. 4:34
- Λατρεύετε τον Αλλάχ και μην αποδίδετε συντρόφους σε Αυτόν, να είστε καλοί στους γονείς, στους συγγενείς, στα ορφανά, στους φτωχούς, στον γείτονα, στον σύντροφο δίπλα σας, στον οδοιπόρο (που συναντάτε) και σε αυτούς (δούλους) που κατέχουν τα δεξιά σας χέρια. Ο Αλλάχ δεν αγαπά εκείνους που είναι υπερήφανοι και καυχησιάρηδες. Να είστε καλοί στους άλλους. Δείξτε έλεος στους αδύναμους. Διατηρήστε τους οικογενειακούς δεσμούς και τιμήστε τους συγγενείς. 4:36
- Μην είστε τσιγκούνηδες. 4:37
- Ο Αλλάχ δεν συγχωρεί να αποδίδονται σ' Αυτόν σύντροφοι, αλλά συγχωρεί ό,τι είναι κατώτερο από αυτό, σε όποιον θέλει. 4:48
- Μην ζηλεύετε τους άλλους. 4:54
- Ο Αλλάχ σας διατάζει να επιστρέφετε τις παρακαταθήκες στους κατόχους τους. Όταν δικάζετε μεταξύ των ανθρώπων, δικάζετε με δικαιοσύνη. 4:58
- Υπακούτε στον Αλλάχ και στον Αγγελιαφόρο Του. Αποδώστε τον δέοντα σεβασμό σε εκείνους που έχουν εξουσία μεταξύ σας. 4:59
- Μην καταπιέζετε τους αδύναμους και τους ευάλωτους. 4:75
- Ό,τι καλό σας έρχεται, είναι από τον Αλλάχ· ό,τι κακό σας βρίσκει, είναι από τους ίδιους σας. 4:79
- Όποιος υπακούει στον Αγγελιαφόρο (Μουχάμαντ ﷺ), έχει υπακούσει στον Αλλάχ. 4:80
- Όποιος μεσιτεύει για καλό σκοπό, θα λάβει μερίδιο από την ανταμοιβή του· και όποιος μεσιτεύει για κακό σκοπό, θα λάβει μερίδιο από το βάρος του. 4:85
- Δεν είναι επιτρεπτό για έναν πιστό να σκοτώνει έναν πιστό, εκτός από λάθος. 4:92
- Όποιος σκοτώνει εσκεμμένα έναν πιστό, η ανταμοιβή του είναι η Κόλαση, όπου θα παραμείνει για πάντα. Η οργή και η κατάρα του Αλλάχ είναι επάνω του, και έχει ετοιμαστεί γι' αυτόν μεγάλη τιμωρία. 4:93
- Όποιος μεταναστεύει (από το σπίτι του) για την υπόθεση του Αλλάχ, θα βρει στη γη πολλά καταφύγια και αφθονία. 4:100
- Να είστε συνεπείς στις προσευχές σας. 4:103
- Μην υποστηρίζετε και μην είστε συνήγοροι εκείνων που προδίδουν τις παρακαταθήκες τους. 4:105
- Ζητήστε τη συγχώρεση του Αλλάχ, ο Αλλάχ είναι σίγουρα Συγχωρητικός, Ελεήμων. 4:106
- Εσείς που πιστεύετε! Να είστε σταθεροί στη δικαιοσύνη, μάρτυρες για τον Αλλάχ, ακόμα κι αν είναι εναντίον σας, ή των γονιών σας, ή των συγγενών σας, είτε είναι πλούσιος είτε φτωχός. Μην καθυστερείτε τη δικαιοσύνη· ενεργήστε άμεσα για να διορθώσετε τις αδικίες. 4:135
- Οι υποκριτές προσπαθούν να εξαπατήσουν τον Αλλάχ, αλλά Αυτός τους εξαπατά. 4:142
- Οι υποκριτές θα βρίσκονται στο κατώτατο σημείο της Φωτιάς· και δεν θα βρείτε γι' αυτούς βοηθό. 4:145
- Ο Αλλάχ δεν αγαπά να λέγεται το κακό δημόσια, εκτός από εκείνον που έχει αδικηθεί. 4:148
- Οι Αγγελιαφόροι ως φορείς καλών ειδήσεων και ως προειδοποιητές, ώστε οι άνθρωποι να μην έχουν επιχείρημα εναντίον του Αλλάχ μετά τους Αγγελιαφόρους. 4:165
- Εκπληρώστε τις συμβάσεις και τις υποσχέσεις σας. 5:1
- Βοηθάτε ο ένας τον άλλον στην αρετή και την ευσέβεια, και μη βοηθάτε ο ένας τον άλλον στην αμαρτία και την εχθρότητα. 5:2
- Μην τρώτε ψοφίμι, αίμα και χοιρινό κρέας. 5:3
- Να είστε δίκαιοι, μην αφήνετε την εχθρότητα και το μίσος προς τους άλλους να σας απομακρύνουν από τη δικαιοσύνη. Να είστε δίκαιοι. Να ξέρετε ότι η δικαιοσύνη είναι πιο κοντά στην ευσέβεια. Μην καθυστερείτε τη δικαιοσύνη· ενεργήστε άμεσα για να διορθώσετε τις αδικίες. 5:8
- Αναζητήστε τα μέσα προσέγγισης στον Αλλάχ και αγωνιστείτε για την υπόθεσή Του όσο μπορείτε. Για να επιτύχετε. 5:35
- Εκπληρώστε τους όρκους και τις συνθήκες σας. 5:89
- Αποφύγετε τα μεθυστικά ποτά και το αλκοόλ. Αποφύγετε αυστηρά τα μεθυστικά (όλα τα είδη αλκοολούχων ποτών), τα τυχερά παιχνίδια, τα είδωλα (λίθινοι βωμοί) και τα βέλη (για αναζήτηση τύχης ή απόφασης), τα οποία είναι όλα βδέλυγμα του έργου του Σατανά. 5:90
- Μην σκοτώνετε θήραμα ενώ βρίσκεστε σε κατάσταση ιχράμ για το χατζ ή την ούμρα (προσκύνημα). 5:95
- Μην ρωτάτε για πράγματα που, αν σας αποκαλυφθούν, μπορεί να σας προκαλέσουν πρόβλημα. 5:101
- Μην βρίζετε τις θεότητες των άλλων. Μην βρίζετε αυτά που (οι άπιστοι) λατρεύουν πέρα από τον Αλλάχ, μήπως και αυτοί βρίσουν τον Αλλάχ από άγνοια. 6:108
- Αν υπακούσετε στην πλειοψηφία αυτών που είναι στη γη, θα σας παραπλανήσουν από τον δρόμο του Αλλάχ. Ακολουθούν μόνο εικασίες και μόνο ψεύδονται. 6:116
- Εγκαταλείψτε (άνθρωποι) κάθε είδους αμαρτία, φανερή και κρυφή. 6:120
- Μην τρώτε (πιστοί) από εκείνο (το κρέας) πάνω στο οποίο δεν έχει ειπωθεί το όνομα του Αλλάχ (τη στιγμή της σφαγής). 6:121
- Όποιον θέλει ο Αλλάχ να οδηγήσει, του ανοίγει το στήθος για το Ισλάμ· και όποιον θέλει να αφήσει να πλανηθεί, του κάνει το στήθος στενό και σφιγμένο. 6:125
- Να είστε μετριοπαθείς στα έξοδα και να αποφεύγετε τη σπατάλη. Προστατεύστε τα δικαιώματα όλων των πλασμάτων. 6:141
- Μην αποδίδετε συντρόφους στον Αλλάχ, να είστε καλοί στους γονείς, μην σκοτώνετε τα παιδιά σας από φόβο φτώχειας, μην πλησιάζετε τις αισχρότητες, μην σκοτώνετε κανέναν που ο Αλλάχ απαγόρευσε, εκτός αν είναι για δίκαιο λόγο. 6:151
- Να είστε τίμιοι· μην απατάτε σε καμία από τις συναλλαγές σας. Μην πλησιάζετε την περιουσία του ορφανού, παρά μόνο για να την βελτιώσετε, δίνετε πλήρες μέτρο και πλήρες βάρος με δικαιοσύνη, όταν μιλάτε, λέτε την αλήθεια, ακόμα κι αν αφορά στενό συγγενή, και εκπληρώστε τη Συνθήκη του Αλλάχ. 6:152
- Ακολουθήστε τον Ευθύ Δρόμο και μην ακολουθείτε (άλλους) δρόμους, γιατί θα σας απομακρύνουν από τον Δρόμο Του. 6:153
- Πες (Μουχάμαντ): "Αλήθεια, η προσευχή μου, η λατρεία μου, η ζωή μου και ο θάνατός μου είναι για τον Αλλάχ, τον Κύριο των κόσμων." 6:162
- Μην είστε αλαζόνες. 7:13
- Μην σας εξαπατά ο Σατανάς. 7:27
- Πες (Μουχάμαντ): "Ο Κύριός μου πρόσταξε τη δικαιοσύνη…" 7:29
- Τηρείτε τα όρια που έθεσε ο Αλλάχ σε όλα. Αποφύγετε την υπέρβαση σε λόγια και πράξεις. Τρώτε και πίνετε, αλλά μην υπερβάλλετε. Φοράτε καλά ρούχα κατά την προσευχή. 7:31
- Ο Αλλάχ δημιούργησε τους ουρανούς και τη γη σε έξι Ημέρες, και μετά εγκαταστάθηκε στον Θρόνο (με τρόπο που αρμόζει στη Μεγαλειότητά Του). 7:54
- Επικαλείστε τον Κύριό σας με ταπείνωση και κρυφά. Αυτός δεν αγαπά τους υπερβάτες. 7:55
- Και μην προκαλείτε φθορά στη γη, αφού αυτή έχει μπει σε τάξη, και επικαλείστε Αυτόν με φόβο και ελπίδα. 7:56
- Αλλά εκείνοι που έκαναν κακές πράξεις και μετά μετανόησαν και πίστεψαν, ο Κύριός σου μετά από αυτά είναι Συγχωρητικός, Ελεήμων. 7:153
- Πες (Μουχάμαντ): "Άνθρωποι! Είμαι ο Αγγελιαφόρος του Αλλάχ προς όλους σας…" 7:158
- Και (όλα) τα Ωραιότερα Ονόματα ανήκουν στον Αλλάχ, γι' αυτό επικαλείστε Τον με αυτά, και αφήστε εκείνους που βλασφημούν τα Ονόματά Του… 7:180
- Όποιον ο Αλλάχ αφήσει να πλανηθεί, δεν έχει οδηγό· και τους αφήνει να περιπλανώνται τυφλά στις παραβάσεις τους. 7:186
- Δείξε συγχώρεση, πρόσταξε το καλό και απομακρύνσου από τους αμαθείς (δηλ. μην τους τιμωρείς). 7:199
- Συγχωρήστε τους άλλους για τα λάθη τους. 7:199
- Και αν σε πειράξει κάποια σκέψη από τον Σατανά, τότε ζήτησε καταφύγιο στον Αλλάχ. Αυτός είναι Πανάκουος, Παντογνώστης. 7:200
- Οι πιστοί είναι μόνο εκείνοι των οποίων οι καρδιές γεμίζουν φόβο όταν αναφέρεται ο Αλλάχ, και όταν τους απαγγέλλονται τα σημεία Του, τους αυξάνουν την πίστη… 8:2
- Μην προδίδετε τον Αλλάχ και τον Αγγελιαφόρο Του, και μην προδίδετε εν γνώσει σας τις παρακαταθήκες σας (και όλα τα καθήκοντα που σας όρισε ο Αλλάχ). 8:27
- Αν φοβάστε και υπακούτε τον Αλλάχ, Αυτός θα σας δώσει μια διάκριση (ένα κριτήριο για να ξεχωρίζετε το αληθινό από το ψεύτικο, ή μια διέξοδο από κάθε δυσκολία). 8:29
- Εκείνοι που απιστούν, ξοδεύουν τον πλούτο τους για να απομακρύνουν (τους ανθρώπους) από τον δρόμο του Αλλάχ, και θα συνεχίσουν να τον ξοδεύουν· αλλά στο τέλος θα γίνει γι' αυτούς μια λύπη. 8:36
- Πες σ' εκείνους που απίστησαν, αν σταματήσουν (την απιστία), θα συγχωρηθούν τα περασμένα τους. Αλλά αν επιστρέψουν (σε αυτήν), τότε τα παραδείγματα των (τιμωρηθέντων) πριν από αυτούς έχουν ήδη προηγηθεί (ως προειδοποίηση). 8:38
- Όταν συναντάτε (μια εχθρική) δύναμη, μείνετε σταθεροί και θυμάστε πολύ το όνομα του Αλλάχ (με γλώσσα και μυαλό), για να επιτύχετε. 8:45
- Μην είστε σαν εκείνους που βγήκαν από τα σπίτια τους με καύχηση και για να φανούν στους ανθρώπους, και (απομάκρυναν τους ανθρώπους) από τον δρόμο του Αλλάχ. 8:47
- Ο Αλλάχ δεν αλλάζει μια χάρη που έδωσε σε έναν λαό, μέχρι να αλλάξουν αυτοί ό,τι είναι μέσα τους. 8:53
- Τα χειρότερα ζωντανά πλάσματα κοντά στον Αλλάχ είναι εκείνοι που απιστούν. 8:55
- Ο Θεός βάζει αγάπη και στοργή ανάμεσα στις καρδιές εκείνων που πιστεύουν σε Αυτόν. 8:63
- Προστατέψτε και βοηθήστε αυτούς που ζητούν προστασία. 9:6
- Δεν αρμόζει στους πολυθεϊστές να συντηρούν τα τζαμιά του Αλλάχ. 9:17
- Αυτοί (οι άπιστοι, οι Εβραίοι και οι Χριστιανοί) θέλουν να σβήσουν το φως του Αλλάχ (με το οποίο στάλθηκε ο Μουχάμαντ ﷺ — ο ισλαμικός μονοθεϊσμός) με τα στόματά τους, αλλά ο Αλλάχ δεν θα επιτρέψει τίποτε άλλο από το να ολοκληρωθεί το Φως Του, ακόμα κι αν το μισούν οι άπιστοι. 9:32
- Οι ελεημοσύνες (ζακάτ) είναι μόνο: 1) για τους φτωχούς, 2) τους απόρους, 3) αυτούς που τις εισπράττουν, 4) για να ελκυσθούν οι καρδιές αυτών που έλκονται προς το Ισλάμ, 5) για την απελευθέρωση των αιχμαλώτων, 6) για τους χρεωμένους, 7) για την υπόθεση του Αλλάχ (για τους μαχητές) και 8) για τον οδοιπόρο. 9:60
- Όποιος αντιτίθεται και δείχνει εχθρότητα στον Αλλάχ και τον Αγγελιαφόρο Του (ﷺ), σίγουρα γι' αυτόν θα είναι η Φωτιά της Κόλασης, όπου θα παραμείνει για πάντα. Αυτή είναι μεγάλη ντροπή. 9:63
- Οι υποκριτές, άνδρες και γυναίκες, είναι ο ένας σαν τον άλλο. Ξέχασαν τον Αλλάχ, έτσι κι Αυτός τους ξέχασε. 9:67
- Αγωνιστείτε για την αγνότητα. Σεβαστείτε την ιερότητα του τζαμιού. 9:108
- Δεν αρμόζει (στον Προφήτη και τους πιστούς) να ζητούν συγχώρεση για τους πολυθεϊστές, ακόμα κι αν είναι συγγενείς, αφού τους έγινε φανερό ότι είναι κάτοικοι της Φωτιάς (επειδή πέθαναν σε κατάσταση απιστίας). 9:113
- Ποιος είναι πιο άδικος από αυτόν που επινοεί ψέματα εναντίον του Αλλάχ ή αρνείται τα σημεία Του; Σίγουρα, οι εγκληματίες ποτέ δεν θα επιτύχουν! 10:17
- Λατρεύουν, πέρα από τον Αλλάχ, πράγματα που δεν μπορούν ούτε να τους βλάψουν ούτε να τους ωφελήσουν, και λένε: "Αυτοί είναι οι μεσολαβητές μας στον Αλλάχ." Πες: "Θα πληροφορήσετε τον Αλλάχ για κάτι που δεν γνωρίζει στους ουρανούς και στη γη;" Δόξα σ' Αυτόν και είναι Υψηλά πάνω από όσα αποδίδουν σ' Αυτόν ως συντρόφους! 10:18
- Η ανταπόδοση για μια κακή πράξη είναι μια παρόμοια κακή πράξη. 10:27
- Αυτός είναι ο Αλλάχ, ο αληθινός Κύριός σας. Τι υπάρχει λοιπόν μετά την αλήθεια, παρά η πλάνη; Πώς λοιπόν απομακρύνεστε; 10:32
- Οι περισσότεροι από αυτούς δεν ακολουθούν παρά εικασίες. Αλήθεια, οι εικασίες σε τίποτα δεν ωφελούν έναντι της αλήθειας. 10:36
- Αλήθεια! Ο Αλλάχ σε τίποτα δεν αδικεί τους ανθρώπους· αλλά οι άνθρωποι αδικούν τους εαυτούς τους. 10:44
- Να ξέρετε ότι η χάρη του Θεού είναι καλύτερη από οτιδήποτε μπορεί ο άνθρωπος να συγκεντρώσει ή να αποθησαυρίσει. 10:58
- Μην είστε από εκείνους που αρνούνται τα σημεία του Αλλάχ, γιατί τότε θα είστε ανάμεσα στους χαμένους. 10:95
- Αν ο Αλλάχ σε αγγίξει με ζημιά, κανείς δεν μπορεί να την απομακρύνει εκτός από Αυτόν· και αν θελήσει καλό για σένα, κανείς δεν μπορεί να αποτρέψει τη χάρη Του, την οποία χαρίζει σε όποιον θέλει από τους δούλους Του. 10:107
- Δεν υπάρχει ζωντανό πλάσμα στη γη που η τροφή του να μην είναι από τον Αλλάχ. Και Αυτός γνωρίζει τη μόνιμη κατοικία του και τον τόπο εναπόθεσής του (στη μήτρα, στον τάφο, κ.λπ.). 11:6
- Αν δώσουμε στον άνθρωπο να γευτεί το έλεός Μας και μετά το αποσύρουμε, αυτός γίνεται απελπισμένος και αχάριστος. 11:9
- Όποιος επιθυμεί την εγκόσμια ζωή και την καλλονή της, σ' αυτούς θα δώσουμε πλήρως την ανταμοιβή των έργων τους σ' αυτήν, και δεν θα τους μειωθεί τίποτα. 11:15
- Δεν τους αδικήσαμε, αλλά αδίκησαν τους εαυτούς τους. Και οι θεοί τους, που επικαλούνταν πέρα από τον Αλλάχ, δεν τους ωφέλησαν σε τίποτα όταν ήρθε η εντολή του Κυρίου σου, και δεν τους πρόσθεσαν παρά μόνο όλεθρο. 11:101
- Την Ημέρα που θα έρθει, κανείς δεν θα μιλήσει χωρίς την άδειά Του (του Αλλάχ). Μερικοί από αυτούς θα είναι άθλιοι και (άλλοι) ευτυχισμένοι. 11:105
- Όσοι είναι άθλιοι, θα είναι στη Φωτιά, όπου θα βγάζουν στεναγμούς και κραυγές. 11:106
- Θα παραμείνουν εκεί για πάντα, όσο θα υπάρχουν οι ουρανοί και η γη, εκτός αν ο Κύριός σου θελήσει διαφορετικά. Αλήθεια, ο Κύριός σου κάνει ό,τι θέλει. 11:107
- Και όσοι είναι ευτυχισμένοι, θα είναι στον Παράδεισο, θα παραμείνουν εκεί για πάντα, όσο θα υπάρχουν οι ουρανοί και η γη, εκτός αν ο Κύριός σου θελήσει διαφορετικά, ως δώρο αδιάκοπο. 11:108
- Μην κλίνετε προς τους άδικους, για να μην σας αγγίξει η Φωτιά, και δεν θα έχετε προστάτες εκτός από τον Αλλάχ, και τότε δεν θα βοηθηθείτε. 11:113
- Εκτελέστε την προσευχή στα δύο άκρα της ημέρας και σε ώρες της νύχτας (δηλαδή τις 5 καθημερινές προσευχές). Οι καλές πράξεις εξαφανίζουν τις κακές (δηλαδή τις μικρές αμαρτίες). 11:114
- Στον Αλλάχ ανήκει το αόρατο των ουρανών και της γης, και σε Αυτόν επιστρέφουν όλες οι υποθέσεις (για κρίση). 11:123
- Η εντολή (ή η κρίση) ανήκει μόνο στον Αλλάχ. Αυτός πρόσταξε να μη λατρεύετε κανέναν άλλον εκτός από Αυτόν (τον μονοθεϊσμό), αυτή είναι η ορθή θρησκεία, αλλά οι περισσότεροι άνθρωποι δεν γνωρίζουν. 12:40
- Μην χάνετε ποτέ την ελπίδα για το έλεος του Αλλάχ. 12:87
- Και οι περισσότεροι άνθρωποι δεν θα πιστέψουν, ακόμα κι αν το επιθυμείτε έντονα. 12:103
- Και οι περισσότεροι από αυτούς δεν πιστεύουν στον Αλλάχ, παρά μόνο αποδίδοντάς Του συντρόφους (δηλαδή είναι πολυθεϊστές). 12:106
- Αυτό (το Κοράνι) δεν είναι πλαστός λόγος, αλλά επιβεβαίωση των προγενέστερων Γραφών (της Τορά, του Ευαγγελίου και των άλλων Γραφών) και λεπτομερής εξήγηση όλων, και καθοδήγηση και έλεος για τους ανθρώπους που πιστεύουν. 12:111
- Ο Αλλάχ αυξάνει τα προς το ζην σε όποιον θέλει και τα περιορίζει (σε όποιον θέλει). 13:26
- Θυμάστε συχνά τον Αλλάχ μέσω του ζικρ. Εκείνοι που πιστεύουν στον Θεό βρίσκουν ικανοποίηση στην ανάμνησή Του. 13:28
- Εκείνοι που πιστεύουν και κάνουν το καλό, τους δίνεται χαρά και γαλήνη ψυχής. 13:29
- Εκείνοι που προτιμούν τη ζωή αυτού του κόσμου από την Άλλη Ζωή, και απομακρύνουν (τους ανθρώπους) από τον δρόμο του Αλλάχ (το Ισλάμ) και αναζητούν στρεβλότητα σε αυτόν — αυτοί βρίσκονται σε βαθιά πλάνη. 14:3
- Εξασκήστε την ταπεινότητα και την ευγνωμοσύνη στη λατρεία. 14:7
- Η παραβολή εκείνων που απιστούν στον Κύριό τους είναι ότι τα έργα τους είναι σαν στάχτη, πάνω στην οποία φυσάει δυνατά ο άνεμος μια θυελλώδη ημέρα· δεν θα μπορέσουν να αποκομίσουν τίποτα από όσα απέκτησαν. 14:18
- Ο Αλλάχ θα στερεώσει αυτούς που πίστεψαν με τον σταθερό λόγο στην εγκόσμια ζωή (δηλαδή θα συνεχίσουν να λατρεύουν μόνο τον Αλλάχ) και στην Άλλη Ζωή. 14:27
- Μην νομίζετε ότι ο Αλλάχ αγνοεί όσα κάνουν οι άδικοι (πολυθεϊστές, καταπιεστές, κ.λπ.), αλλά τους δίνει αναβολή μέχρι την Ημέρα που τα μάτια θα είναι διάπλατα ανοιχτά από τον τρόμο. 14:42
- Για να ανταμείψει ο Αλλάχ κάθε ψυχή σύμφωνα με όσα απέκτησε. Αλήθεια, ο Αλλάχ είναι γρήγορος στον λογαριασμό. 14:51
- Και αλήθεια, δημιουργήσαμε τον άνθρωπο από πηλό που κάνει ήχο, από μαύρη λάσπη που έχει μεταβληθεί. 15:26
- Και τα τζιν, τα δημιουργήσαμε προηγουμένως από φωτιά που καίει χωρίς καπνό. 15:27
- Έχει (η Κόλαση) επτά πύλες, για κάθε πύλη υπάρχει (ειδική) κατηγορία αμαρτωλών. 15:44
- Δημιούργησε τον άνθρωπο από μια σταγόνα σπέρματος (μείγμα ανδρικού και γυναικείου σωματικού υγρού), και να, αυτός (ο άνθρωπος) γίνεται φανερός αντίπαλος. 16:4
- Και τα ζώα, τα δημιούργησε για εσάς· σ' αυτά υπάρχει ζεστασιά (ζεστά ρούχα) και πολλά οφέλη, και από αυτά τρώτε. 16:5
- Και (δημιούργησε) τα άλογα, τα μουλάρια και τους γαϊδάρους, για να τα ιππεύετε και ως στολίδι. Και δημιουργεί (άλλα) πράγματα που δεν γνωρίζετε. 16:8
- Αυτός είναι που κατεβάζει νερό (βροχή) από τον ουρανό· από αυτό πίνετε και από αυτό φυτρώνει η βλάστηση με την οποία βόσκετε τα ζώα σας. 16:10
- Αυτός είναι που υπέταξε τη θάλασσα (για εσάς), για να τρώτε από αυτήν φρέσκο κρέας (ψάρι) και να βγάζετε από αυτήν στολίδια που φοράτε. 16:14
- Τοποθέτησε στη γη βουνά ακλόνητα, για να μη σείεται μαζί σας, και ποτάμια και δρόμους, για να οδηγείστε. 16:15
- Είναι αυτός που δημιουργεί σαν εκείνον που δεν δημιουργεί; Δεν θα το θυμηθείτε; 16:17
- Αν μετρούσατε τις χάρες του Αλλάχ, δεν θα μπορούσατε ποτέ να τις αριθμήσετε. 16:18
- Ο Αλλάχ γνωρίζει τι κρύβετε και τι φανερώνετε. 16:19
- Εκείνα που επικαλούνται (οι πολυθεϊστές) πέρα από τον Αλλάχ, δεν έχουν δημιουργήσει τίποτα, αλλά τα ίδια έχουν δημιουργηθεί. 16:20
- (Είναι) νεκρά, άψυχα, και δεν γνωρίζουν πότε θα αναστηθούν. 16:21
- Ο λόγος Μας για ένα πράγμα, όταν το θελήσουμε, είναι μόνο να του πούμε: "Γίνου!" και γίνεται. 16:40
- Αυτοί που μηχανεύονται κακά σχέδια, αισθάνονται ασφαλείς ότι ο Αλλάχ δεν θα τους κάνει να βυθιστούν στη γη, ή ότι το μαρτύριο δεν θα τους έρθει από όπου δεν περιμένουν; 16:45
- Όλες οι ευλογίες και τα καλά πράγματα που έχετε, είναι από τον Αλλάχ. Κατόπιν, όταν σας βρει μια συμφορά, τότε σε Αυτόν φωνάζετε για βοήθεια. 16:53
- Κατόπιν, όταν απομακρύνει τη συμφορά από εσάς, τότε μερικοί από εσάς αποδίδουν συντρόφους στον Κύριό τους (τον Αλλάχ). 16:54
- Στα ζώα υπάρχει ένα μάθημα για εσάς. Σας δίνουμε να πίνετε από αυτό που βρίσκεται στις κοιλιές τους, ανάμεσα σε περιττώματα και αίμα, καθαρό γάλα, ευχάριστο για όσους το πίνουν. 16:66
- Μην αποδίδετε λοιπόν στον Αλλάχ ομοιώματα (γιατί τίποτα δεν μοιάζει με Αυτόν, ούτε Αυτός μοιάζει με τίποτα). Αλήθεια, ο Αλλάχ γνωρίζει, ενώ εσείς δεν γνωρίζετε. 16:74
- Να ξέρετε ότι ο Θεός έδωσε στους ανθρώπους την ακοή, την όραση, τη νοημοσύνη και τα συναισθήματα, ώστε να είναι ευγνώμονες. 16:78
- Αποφύγετε την απληστία και τη φιλαργυρία. 16:97
- Όταν θέλετε να διαβάσετε το Κοράνι, ζητήστε καταφύγιο στον Αλλάχ από τον Σατανά, τον καταραμένο. 16:98
- Να ξέρετε ότι ένα κακό που διαπράχθηκε από άγνοια συγχωρείται αν ο άνθρωπος μετανοήσει και διορθωθεί. 16:119
- Προσκαλέστε (Μουχάμαντ) στον δρόμο του Κυρίου σας (το Ισλάμ) με σοφία και καλή νουθεσία, και συζητήστε μαζί τους με τον καλύτερο τρόπο. Η πρόσκληση των άλλων στον δρόμο του Θεού πρέπει να γίνεται με σοφία και καλοσύνη. 16:125
- Ο Αλλάχ είναι με εκείνους που Τον φοβούνται (που εκπληρώνουν το καθήκον τους προς Αυτόν) και με εκείνους που είναι ευεργέτες. 16:128
- Αυτό το Κοράνι οδηγεί σε αυτό που είναι πιο δίκαιο και ορθό. 17:9
- Κανείς δεν μπορεί να βαστάξει το βάρος των αμαρτιών του άλλου. 17:15
- Όποιος επιθυμεί την Άλλη Ζωή και αγωνίζεται γι' αυτήν, με τον αγώνα που της αξίζει, ενώ είναι πιστός, τότε αυτοί, ο αγώνας τους θα εκτιμηθεί και θα ανταμειφθεί (από τον Αλλάχ). 17:19
- Τιμήστε τους γονείς σας και συμπεριφέρεστε τους με καλοσύνη. Να είστε ευσεβείς προς τους γονείς. Μην τους λέτε ούτε μια λέξη ασέβειας. Και ο Κύριός σας έχει ορίσει να μη λατρεύετε κανέναν άλλον εκτός από Αυτόν. Και να είστε καλοί με τους γονείς σας. Αν κάποιος από αυτούς ή και οι δύο φτάσουν σε βαθιά γεράματα στη ζωή σας, μην τους πείτε "Ουφ!" και μην τους αποπαίρνετε, αλλά απευθυνθείτε τους με λόγια τιμής. 17:23
- Και χαμηλώστε για χάρη τους το φτερό της ταπεινότητας και της συμπόνιας, και πείτε: "Κύριέ μου, σπλαχνίσου τους, όπως με ανέθρεψαν όταν ήμουν μικρός." 17:24
- Αλήθεια, οι σπάταλοι είναι αδέρφια των δαιμόνων, και ο Σατανάς είναι αχάριστος στον Κύριό του. 17:27
- Μην σπαταλάτε χρήματα. 17:29
- Μην σκοτώνετε τα παιδιά σας από φόβο φτώχειας. 17:31
- Μην πλησιάζετε τη μοιχεία. Προστατέψτε την ιερότητα του γάμου και αποφύγετε τη μοιχεία. 17:32
- Δίνετε πλήρες μέτρο όταν μετράτε, και ζυγίζετε με σωστό ζυγό. Αυτό είναι καλύτερο (πιο συμφέρον) και καλύτερο στο τέλος. 17:35
- Μην ακολουθείς (άνθρωπε, δηλ. μην λες, μην κάνεις, ή μην καταθέτεις κ.λπ.) αυτό για το οποίο δεν έχεις γνώση (π.χ. κάποιος να λέει: "Είδα", ενώ δεν είδε, ή "Άκουσα", ενώ δεν άκουσε). 17:36
- Να είστε ταπεινοί και μην είστε αλαζόνες. Μην περπατάτε στη γη με έπαρση και αλαζονεία. Αλήθεια, δεν μπορείτε να σχίσετε τη γη, ούτε να φτάσετε το ύψος των βουνών. 17:37
- Ο Κύριός σας σας γνωρίζει καλύτερα· αν θέλει, θα σας σπλαχνιστεί, ή αν θέλει, θα σας τιμωρήσει. 17:54
- Όποιος είναι τυφλός σε αυτόν τον κόσμο (δηλαδή δεν βλέπει τα σημεία του Αλλάχ και δεν πιστεύει σε Αυτόν), θα είναι τυφλός και στην Άλλη Ζωή, και ακόμα πιο απομακρυσμένος από τον Δρόμο. 17:72
- Τηρείτε τις καθορισμένες ώρες της προσευχής. 17:78
- Αλήθεια, έχουμε εξηγήσει διεξοδικά στους ανθρώπους σε αυτό το Κοράνι κάθε είδους παραδείγματα, αλλά οι περισσότεροι άνθρωποι απορρίπτουν (την αλήθεια) και δεν αποδέχονται τίποτα άλλο παρά την απιστία. 17:89
- Έχουμε παραθέσει σε αυτό το Κοράνι κάθε είδους παράδειγμα για τους ανθρώπους. Αλλά ο άνθρωπος είναι πιο φιλόνικος από οτιδήποτε άλλο. 18:54
- Αυτή θα είναι η ανταμοιβή τους, η Κόλαση· επειδή απίστησαν και πήραν τα σημεία Μου και τους Αγγελιαφόρους Μου ως χλευασμό και εμπαιγμό. 18:106
- Δεν αρμόζει (στη Μεγαλειότητα) του Αλλάχ να αποκτήσει παιδί (αυτό αναφέρεται στη συκοφαντία των Χριστιανών εναντίον του Αλλάχ, λέγοντας ότι ο Ιησούς είναι γιος του Θεού). Δόξα σ' Αυτόν (και είναι Υψηλά πάνω από όσα αποδίδουν σ' Αυτόν). 19:35
- Μιλάτε στους ανθρώπους με ευγένεια. 20:44
- Συναγωνιστείτε ο ένας τον άλλον στην καλοσύνη. 21:90
- Αποφύγετε τα μάταια λόγια. 23:3
- Προστατέψτε την αιδώ σας. 23:5
- Προστατέψτε την καρδιά σας από αμαρτωλές ροπές. 23:97
- Συγχωρήστε τους άλλους και συγχωρέστε τα λάθη τους. 24:22
